static void trim(char*s){if(!s)return;char*p=s;while(isspace((unsigned char)*p))p++;if(p!=s)memmove(s,p,strlen(p)+1);size_t n=strlen(s);while(n&&isspace((unsigned char)s[n-1]))s[--n]=0;}
static int textcpy(char*d,size_t cap,const char*s){if(!d||!cap||!s||strlen(s)>=cap)return-1;memcpy(d,s,strlen(s)+1);return 0;}
static const char*json_key(const char*j,const char*k){char pat[128];snprintf(pat,sizeof(pat),"\"%s\"",k);return strstr(j,pat);}
static int json_string(const char*j,const char*k,char*out,size_t cap){const char*p=json_key(j,k);if(!p)return-1;p=strchr(p,':');if(!p)return-1;p++;while(isspace((unsigned char)*p))p++;if(*p!='\"')return-1;p++;size_t n=0;while(*p&&*p!='\"'){if(*p=='\\'&&p[1])p++;if(n+1>=cap)return-1;out[n++]=*p++;}if(*p!='\"')return-1;out[n]=0;return 0;}
static int json_u32(const char*j,const char*k,uint32_t*out){const char*p=json_key(j,k);if(!p)return-1;p=strchr(p,':');if(!p)return-1;p++;while(isspace((unsigned char)*p))p++;char*e=NULL;unsigned long v=strtoul(p,&e,10);if(e==p||v>0xffffffffUL)return-1;*out=(uint32_t)v;return 0;}
static int json_bool(const char*j,const char*k,uint8_t*out){const char*p=json_key(j,k);if(!p)return-1;p=strchr(p,':');if(!p)return-1;p++;while(isspace((unsigned char)*p))p++;if(!strncmp(p,"true",4)){*out=1;return 0;}if(!strncmp(p,"false",5)){*out=0;return 0;}return-1;}
static uint32_t first_u32(const char*j,const char*const*keys,size_t n,uint32_t def){uint32_t v;for(size_t i=0;i<n;i++)if(!json_u32(j,keys[i],&v))return v;return def;}
static int weight_path(const char*p){size_t n=strlen(p);if(n>=12&&!strcmp(p+n-12,".safetensors"))return 1;if(n>=5&&!strcmp(p+n-5,".gguf"))return 1;return 0;}
static int selected_path(const char*p,const QrxAuraOriginModelSpec*s){size_t n=strlen(p);int weight=weight_path(p);if(weight&&s&&s->file_filter[0]&&strcmp(s->file_filter,"*")&&strcmp(p,s->file_filter))return 0;if(!strcmp(p,"LICENSE")||!strcmp(p,"THIRD_PARTY_NOTICES.md")||!strcmp(p,"config.json")||!strcmp(p,"generation_config.json")||!strcmp(p,"model.safetensors.index.json")||!strcmp(p,"params")||!strcmp(p,"params.json"))return 1;if(strstr(p,"tokenizer")||strstr(p,"processor")||strstr(p,"configuration_")||strstr(p,"modeling_")||strstr(p,"encoding_")||strstr(p,"vision_processing")||strstr(p,"media_utils"))return 1;if(weight)return 1;if(n>=6&&!strcmp(p+n-6,".model"))return 1;if(!strcmp(p,"vocab.json")||!strcmp(p,"merges.txt")||!strcmp(p,"chat_template.jinja"))return 1;return 0;}
static QrxAuraModelAssetKind kind_for(const char*p){size_t n=strlen(p);if(weight_path(p))return QRX_AURA_ASSET_WEIGHT_CHUNK;if(strstr(p,"token")||!strcmp(p,"vocab.json")||!strcmp(p,"merges.txt")||(n>=6&&!strcmp(p+n-6,".model"))||strstr(p,"chat_template"))return QRX_AURA_ASSET_TOKENIZER;if(n>=3&&!strcmp(p+n-3,".py"))return QRX_AURA_ASSET_ADAPTER;return QRX_AURA_ASSET_CONFIG;}
