static int make_api(char*out,size_t cap,const char*base,const char*repo,const char*rev){int n;if(!strcmp(rev,"main"))n=snprintf(out,cap,"%s/models/%s",base,repo);else n=snprintf(out,cap,"%s/models/%s/revision/%s",base,repo,rev);return n<0||(size_t)n>=cap?-1:0;}
static int sha3_text(const char*s,char out[65]){EVP_MD_CTX*c=EVP_MD_CTX_new();unsigned char h[32];unsigned n=0;if(!c)return-1;int ok=EVP_DigestInit_ex(c,EVP_sha3_256(),NULL)==1&&EVP_DigestUpdate(c,s,strlen(s))==1&&EVP_DigestFinal_ex(c,h,&n)==1&&n==32;EVP_MD_CTX_free(c);if(!ok)return-1;static const char*x="0123456789abcdef";for(int i=0;i<32;i++){out[i*2]=x[h[i]>>4];out[i*2+1]=x[h[i]&15];}out[64]=0;return 0;}
