static uint64_t mib_bytes(const char*s){unsigned long long v=s&&*s?strtoull(s,NULL,10):0;return v>UINT64_MAX/(1024ull*1024ull)?0:v*1024ull*1024ull;}
int qrx_aura_origin_catalog_load(const char*path,QrxAuraOriginModelSpec*out,size_t cap,size_t*count){if(!path||!out||!cap||!count)return-1;*count=0;FILE*f=fopen(path,"rb");if(!f)return-2;char line[4096];int hdr=0,ver=0;while(fgets(line,sizeof(line),f)){trim(line);if(!line[0]||line[0]=='#')continue;if(!hdr){if(!strcmp(line,"QRXAURA-ORIGIN-CATALOG-1"))ver=1;else if(!strcmp(line,"QRXAURA-ORIGIN-CATALOG-2"))ver=2;else{fclose(f);return-3;}hdr=1;continue;}if(*count>=cap){fclose(f);return-4;}char*fld[24]={0};size_t n=0;char*save=NULL;for(char*q=strtok_r(line,"|",&save);q&&n<24;q=strtok_r(NULL,"|",&save))fld[n++]=q;if((ver==1&&n!=11)||(ver==2&&n!=22)){fclose(f);return-5;}QrxAuraOriginModelSpec*x=&out[(*count)++];memset(x,0,sizeof(*x));x->version=(uint32_t)ver;textcpy(x->model_id,sizeof(x->model_id),fld[0]);textcpy(x->family,sizeof(x->family),fld[1]);textcpy(x->repo_id,sizeof(x->repo_id),fld[2]);textcpy(x->revision,sizeof(x->revision),fld[3]);textcpy(x->expected_license,sizeof(x->expected_license),fld[4]);textcpy(x->architecture_hint,sizeof(x->architecture_hint),fld[5]);textcpy(x->runtime_id,sizeof(x->runtime_id),fld[6]);textcpy(x->quantization,sizeof(x->quantization),fld[7]);x->tier=(QrxAuraModelTier)strtoul(fld[8],NULL,10);x->recommended=(uint8_t)strtoul(fld[9],NULL,10);x->moe_hint=(uint8_t)strtoul(fld[10],NULL,10);if(ver==1){x->quality_bps=x->coding_bps=x->reasoning_bps=9000;x->rag_bps=8500;x->tool_use_bps=9000;x->auto_default=x->recommended;textcpy(x->file_filter,sizeof(x->file_filter),"*");}else{x->min_memory_bytes=mib_bytes(fld[11]);x->recommended_memory_bytes=mib_bytes(fld[12]);x->min_milli_tokens_per_second=strtoull(fld[13],NULL,10);x->quality_bps=parse_bps(fld[14],9000);x->coding_bps=parse_bps(fld[15],x->quality_bps);x->reasoning_bps=parse_bps(fld[16],x->quality_bps);x->rag_bps=parse_bps(fld[17],x->quality_bps);x->tool_use_bps=parse_bps(fld[18],x->quality_bps);x->auto_default=(uint8_t)strtoul(fld[19],NULL,10);x->gated_optional=(uint8_t)strtoul(fld[20],NULL,10);textcpy(x->file_filter,sizeof(x->file_filter),fld[21]);if(!x->file_filter[0])textcpy(x->file_filter,sizeof(x->file_filter),"*");if(x->recommended_memory_bytes&&x->min_memory_bytes&&x->recommended_memory_bytes<x->min_memory_bytes){fclose(f);return-6;}}}fclose(f);return hdr?0:-3;}

int qrx_aura_origin_spec_profile(const QrxAuraOriginModelSpec*s,QrxAuraModelCapabilityProfile*p){if(!s||!p||s->tier<QRX_AURA_TIER_NANO||s->tier>QRX_AURA_TIER_K3_CLASS)return-1;memset(p,0,sizeof(*p));p->version=QRX_AURA_FABRIC_VERSION;textcpy(p->model_id,sizeof(p->model_id),s->model_id);textcpy(p->model_version,sizeof(p->model_version),"bootstrap");textcpy(p->family,sizeof(p->family),s->family);textcpy(p->runtime_id,sizeof(p->runtime_id),s->runtime_id);textcpy(p->quantization,sizeof(p->quantization),s->quantization);p->tier=s->tier;p->min_memory_bytes=s->min_memory_bytes?s->min_memory_bytes:(s->tier==QRX_AURA_TIER_NANO?2ull<<30:s->tier==QRX_AURA_TIER_EDGE?4ull<<30:s->tier==QRX_AURA_TIER_LOCAL?8ull<<30:s->tier==QRX_AURA_TIER_CLUSTER?16ull<<30:s->tier==QRX_AURA_TIER_K2_CLASS?32ull<<30:64ull<<30);p->recommended_memory_bytes=s->recommended_memory_bytes?s->recommended_memory_bytes:p->min_memory_bytes*2;p->min_storage_bytes=1;p->min_aggregate_milli_tokens_per_second=s->min_milli_tokens_per_second?s->min_milli_tokens_per_second:1;p->min_pods=s->tier>=QRX_AURA_TIER_K2_CLASS?2:1;p->min_network_mbps=s->tier>=QRX_AURA_TIER_K2_CLASS?100:0;p->max_latency_ms=1000;p->min_reliability_bps=0;p->min_cache_hit_bps=0;p->min_expert_locality_bps=0;p->max_context_tokens=2048;p->quality_bps=s->quality_bps?s->quality_bps:9000;p->coding_bps=s->coding_bps?s->coding_bps:p->quality_bps;p->reasoning_bps=s->reasoning_bps?s->reasoning_bps:p->quality_bps;p->rag_bps=s->rag_bps?s->rag_bps:p->quality_bps;p->tool_use_bps=s->tool_use_bps?s->tool_use_bps:p->quality_bps;p->is_moe=s->moe_hint;p->supports_single_device=s->tier<QRX_AURA_TIER_K2_CLASS;return qrx_aura_model_profile_validate(p);}
static uint32_t spec_task_score(const QrxAuraOriginModelSpec*s,QrxAuraTaskClass t){switch(t){case QRX_AURA_TASK_CODING:return s->coding_bps;case QRX_AURA_TASK_REASONING:return s->reasoning_bps;case QRX_AURA_TASK_RAG:return s->rag_bps;case QRX_AURA_TASK_TOOL_USE:return s->tool_use_bps;default:return s->quality_bps;}}
int qrx_aura_origin_auto_select(const QrxAuraOriginModelSpec*specs,size_t count,const QrxAuraPodCapacity*pod,QrxAuraTaskClass task,uint32_t complexity,uint8_t allow_gated,QrxAuraOriginAutoSelection*out){if(!specs||!count||!pod||!out||qrx_aura_pod_capacity_validate(pod)||task<QRX_AURA_TASK_CHAT||task>QRX_AURA_TASK_TOOL_USE)return-1;if(complexity>10000)complexity=10000;QrxAuraModelTier max_tier=complexity<=3000?QRX_AURA_TIER_NANO:complexity<=7000?QRX_AURA_TIER_EDGE:complexity<=9000?QRX_AURA_TIER_LOCAL:QRX_AURA_TIER_K3_CLASS;int found=-1;uint64_t best=0;QrxAuraModelCapabilityProfile bestp;memset(&bestp,0,sizeof(bestp));for(size_t i=0;i<count;i++){const QrxAuraOriginModelSpec*s=&specs[i];if(!s->auto_default||(s->gated_optional&&!allow_gated)||s->tier>max_tier)continue;QrxAuraModelCapabilityProfile p;if(qrx_aura_origin_spec_profile(s,&p))continue;if(pod->free_memory_bytes<p.min_memory_bytes||pod->measured_milli_tokens_per_second<p.min_aggregate_milli_tokens_per_second)continue;uint64_t score=(uint64_t)spec_task_score(s,task)*1000ull+(uint64_t)p.quality_bps*100ull+(uint64_t)s->recommended*250000ull;score+=(uint64_t)s->tier*25000ull;uint64_t spare=pod->free_memory_bytes-p.min_memory_bytes;score+=spare>(8ull<<30)?8000ull:(spare>>20);if(found<0||score>best||(score==best&&strcmp(s->model_id,specs[found].model_id)<0)){found=(int)i;best=score;bestp=p;}}if(found<0){/* graceful degradation: allow any smaller AUTO model that fits */for(size_t i=0;i<count;i++){const QrxAuraOriginModelSpec*s=&specs[i];if(!s->auto_default||(s->gated_optional&&!allow_gated))continue;QrxAuraModelCapabilityProfile p;if(qrx_aura_origin_spec_profile(s,&p))continue;if(pod->free_memory_bytes<p.min_memory_bytes||pod->measured_milli_tokens_per_second<p.min_aggregate_milli_tokens_per_second)continue;uint64_t score=(uint64_t)spec_task_score(s,task)*1000ull;if(found<0||score>best){found=(int)i;best=score;bestp=p;}}}if(found<0)return-2;memset(out,0,sizeof(*out));out->version=1;out->spec_index=(uint32_t)found;out->spec=specs[found];out->profile=bestp;out->degraded=(uint8_t)(out->spec.tier>max_tier?1:0);return 0;}

static int immutable_revision(const char *s){size_t n=s?strlen(s):0;if(n!=40&&n!=64)return 0;for(size_t i=0;i<n;i++)if(!isxdigit((unsigned char)s[i]))return 0;return 1;}

