int qrx_aura_origin_materialize(const QrxAuraOriginSourceMap*m,QrxStorageFs*fs,const char*dir){if(!m||!fs||!dir||!dir[0])return-1;MKDIR(dir);for(uint32_t i=0;i<m->file_count;i++){uint8_t*b=NULL;size_t n=0;if(qrx_storage_fs_read(fs,m->files[i].content_root,&b,&n)||n!=m->files[i].bytes){free(b);return-2;}char p[1400];if(mkdirs_for_file(dir,m->files[i].path,p)){free(b);return-3;}FILE*f=fopen(p,"wb");if(!f){free(b);return-4;}size_t wrote=fwrite(b,1,n,f);int close_rc=fclose(f);if(wrote!=n||close_rc){free(b);return-4;}free(b);}return 0;}

int qrx_aura_origin_catalog_announcement(const QrxAuraOriginSeedResult*seed,const QrxAuraOriginModelSpec*spec,const char*publisher,uint64_t seq,uint64_t from,uint64_t until,QrxAuraModelCatalogAnnouncement*out){
    if(!seed||!spec||!publisher||!publisher[0]||!seq||until<from||!out)return-1;memset(out,0,sizeof(*out));out->version=1;if(textcpy(out->publisher_id,sizeof(out->publisher_id),publisher))return-1;out->sequence=seq;out->valid_from_height=from;out->valid_until_height=until;out->manifest=seed->distribution_manifest;if(textcpy(out->manifest_root,sizeof(out->manifest_root),seed->distribution_manifest_root))return-1;QrxAuraModelCapabilityProfile*p=&out->capability;memset(p,0,sizeof(*p));p->version=1;textcpy(p->model_id,sizeof(p->model_id),seed->registry_record.model_id);textcpy(p->model_version,sizeof(p->model_version),seed->registry_record.model_version);textcpy(p->family,sizeof(p->family),spec->family);textcpy(p->runtime_id,sizeof(p->runtime_id),spec->runtime_id);textcpy(p->quantization,sizeof(p->quantization),spec->quantization);p->tier=spec->tier;p->min_memory_bytes=seed->registry_record.min_memory_bytes;p->recommended_memory_bytes=spec->recommended_memory_bytes?spec->recommended_memory_bytes:(p->min_memory_bytes>UINT64_MAX/2?p->min_memory_bytes:p->min_memory_bytes*2);p->min_storage_bytes=seed->distribution_manifest.total_bytes;p->min_aggregate_milli_tokens_per_second=spec->min_milli_tokens_per_second?spec->min_milli_tokens_per_second:1;p->min_pods=spec->tier>=QRX_AURA_TIER_K2_CLASS?2:1;p->min_network_mbps=spec->tier>=QRX_AURA_TIER_K2_CLASS?100:20;p->max_latency_ms=1000;p->min_reliability_bps=7000;p->max_context_tokens=seed->distribution_manifest.max_context_tokens;p->quality_bps=spec->quality_bps?spec->quality_bps:9000;p->coding_bps=spec->coding_bps?spec->coding_bps:p->quality_bps;p->reasoning_bps=spec->reasoning_bps?spec->reasoning_bps:p->quality_bps;p->rag_bps=spec->rag_bps?spec->rag_bps:p->quality_bps;p->tool_use_bps=spec->tool_use_bps?spec->tool_use_bps:p->quality_bps;p->is_moe=seed->registry_record.is_moe;p->supports_single_device=spec->tier<QRX_AURA_TIER_K2_CLASS?1:0;out->popularity_bps=spec->recommended?8000:5000;out->priority_bps=spec->recommended?8500:5000;out->recommended=spec->recommended;return qrx_aura_model_manifest_validate(&out->manifest)||qrx_aura_model_profile_validate(p)?-2:0;
}
int qrx_aura_origin_availability_announcement(const QrxAuraOriginSeedResult*seed,const char*provider,const char*pod,const char*region,const char*endpoint,uint64_t seq,uint64_t from,uint64_t until,uint32_t bandwidth,uint32_t latency,uint32_t reliability,QrxAuraModelAvailabilityAnnouncement*out){
    if(!seed||!provider||!pod||!region||!endpoint||!seq||until<from||!out)return-1;memset(out,0,sizeof(*out));out->version=1;textcpy(out->provider_id,sizeof(out->provider_id),provider);textcpy(out->pod_id,sizeof(out->pod_id),pod);textcpy(out->region,sizeof(out->region),region);textcpy(out->endpoint,sizeof(out->endpoint),endpoint);textcpy(out->model_id,sizeof(out->model_id),seed->distribution_manifest.model_id);textcpy(out->model_version,sizeof(out->model_version),seed->distribution_manifest.model_version);textcpy(out->manifest_root,sizeof(out->manifest_root),seed->distribution_manifest_root);out->sequence=seq;out->valid_from_height=from;out->valid_until_height=until;out->bandwidth_mbps=bandwidth;out->latency_ms=latency;out->reliability_bps=reliability>10000?10000:reliability;out->full_model=1;return qrx_aura_model_availability_validate(out,from);
}

static int parse_hf_origin(const char*u,char repo[QRX_AURA_ORIGIN_REPO_MAX],char rev[QRX_AURA_ORIGIN_REV_MAX],char filter[QRX_AURA_ORIGIN_FILTER_MAX]){if(!u||strncmp(u,"hf://",5))return-1;const char*p=u+5,*at=strrchr(p,'@');if(!at||at==p||!at[1])return-1;size_t rn=(size_t)(at-p);if(rn>=QRX_AURA_ORIGIN_REPO_MAX)return-1;memcpy(repo,p,rn);repo[rn]=0;const char*hash=strchr(at+1,'#');size_t vn=hash?(size_t)(hash-(at+1)):strlen(at+1);if(!vn||vn>=QRX_AURA_ORIGIN_REV_MAX)return-1;memcpy(rev,at+1,vn);rev[vn]=0;if(filter){filter[0]=0;if(hash&&hash[1]){if(strlen(hash+1)>=QRX_AURA_ORIGIN_FILTER_MAX)return-1;strcpy(filter,hash+1);}else strcpy(filter,"*");}return 0;}
static int asset_fetch_known(const QrxAuraOriginConfig*c,const char*repo,const char*rev,const char*path,uint64_t declared,QrxStorageFs*fs,const char*expect){if(qrx_storage_fs_has(fs,expect)==1)return 0;char u[2048];if(make_url(u,sizeof(u),c->hf_base_url,repo,rev,path))return-1;if(declared<=64u*1024u*1024u){Mem b={0};if(http_mem(c,u,(size_t)declared+1,&b)||b.n!=declared)return-2;char got[65];int rc=seed_bytes(fs,b.p,b.n,got);free(b.p);return rc||strcmp(got,expect)?-3:0;}ensure_dir(c->work_dir);char h[65],tmp[1400],got[65];sha3_text(u,h);snprintf(tmp,sizeof(tmp),"%s/%s.part",c->work_dir,h);if(http_file_resume(c,u,tmp,declared,NULL,NULL))return-4;if(qrx_storage_fs_put_file(fs,tmp,got)){return-5;}remove(tmp);return strcmp(got,expect)?-6:0;}
static int rebuild_origin_map(const QrxAuraOriginConfig*c,const QrxAuraModelManifest*m,QrxAuraOriginSourceMap*map,Mem*cfgmem){char repo[QRX_AURA_ORIGIN_REPO_MAX],rev[QRX_AURA_ORIGIN_REV_MAX],filter[QRX_AURA_ORIGIN_FILTER_MAX];if(parse_hf_origin(m->origin_uri,repo,rev,filter))return-1;QrxAuraOriginModelSpec s={0};s.version=2;textcpy(s.model_id,sizeof(s.model_id),m->model_id);textcpy(s.family,sizeof(s.family),m->family);textcpy(s.repo_id,sizeof(s.repo_id),repo);textcpy(s.revision,sizeof(s.revision),rev);textcpy(s.expected_license,sizeof(s.expected_license),m->license_id);textcpy(s.file_filter,sizeof(s.file_filter),filter);QrxAuraOriginRepoMetadata md;if(qrx_aura_hf_repo_resolve(c,&s,&md)||strcmp(md.resolved_revision,rev)||md.file_count!=m->asset_count)return-2;char paths[QRX_AURA_ORIGIN_MAX_FILES][QRX_AURA_ORIGIN_PATH_MAX];for(uint32_t i=0;i<md.file_count;i++)textcpy(paths[i],sizeof(paths[i]),md.files[i].path);for(uint32_t i=0;i<md.file_count;i++)for(uint32_t j=i+1;j<md.file_count;j++)if(strcmp(paths[i],paths[j])>0){char t[QRX_AURA_ORIGIN_PATH_MAX];memcpy(t,paths[i],sizeof(t));memcpy(paths[i],paths[j],sizeof(t));memcpy(paths[j],t,sizeof(t));}memset(map,0,sizeof(*map));map->version=1;textcpy(map->repo_id,sizeof(map->repo_id),repo);textcpy(map->revision,sizeof(map->revision),rev);map->file_count=md.file_count;for(uint32_t i=0;i<md.file_count;i++){QrxAuraOriginSeededFile*f=&map->files[i];textcpy(f->path,sizeof(f->path),paths[i]);textcpy(f->content_root,sizeof(f->content_root),m->assets[i].content_root);f->bytes=m->assets[i].bytes;f->kind=m->assets[i].kind;f->layer_first=m->assets[i].layer_first;f->layer_count=m->assets[i].layer_count;f->expert_first=m->assets[i].expert_first;f->expert_count=m->assets[i].expert_count;}if(cfgmem){memset(cfgmem,0,sizeof(*cfgmem));get_small(c,&md,"config.json",cfgmem);}return 0;}
static int origin_fetch_selected(QrxAuraOriginFallbackFetchContext*c,const QrxAiModelRecord*model,const QrxAuraModelCachePlacement*p,const QrxAuraModelCatalogAnnouncement*a,char out[65]){QrxAuraOriginSourceMap map;Mem cfg={0};if(rebuild_origin_map(&c->origin,&a->manifest,&map,&cfg))return-1;char mc[65];if(qrx_ai_model_commitment(model,mc)){free(cfg.p);return-1;}uint64_t fetched=0;
    for(uint32_t i=0;i<a->manifest.asset_count;i++){const QrxAuraModelAsset*x=&a->manifest.assets[i];if(!x->required_for_boot)continue;if(asset_fetch_known(&c->origin,map.repo_id,map.revision,map.files[i].path,x->bytes,c->local_cache,x->content_root)){free(cfg.p);return-2;}fetched+=x->bytes;}
    uint32_t cand[QRX_AURA_MODEL_MANIFEST_MAX_ASSETS],cn=0;for(uint32_t i=0;i<a->manifest.asset_count;i++)if(a->manifest.assets[i].kind==QRX_AURA_ASSET_WEIGHT_CHUNK||a->manifest.assets[i].kind==QRX_AURA_ASSET_SHARED_WEIGHTS||a->manifest.assets[i].kind==QRX_AURA_ASSET_EXPERT_PACK)cand[cn++]=i;if(!cn){free(cfg.p);return-3;}EVP_MD_CTX*h=EVP_MD_CTX_new();unsigned char d[32];unsigned dn=0;if(!h||EVP_DigestInit_ex(h,EVP_sha3_256(),NULL)!=1||EVP_DigestUpdate(h,p->pod_id,strlen(p->pod_id))!=1||EVP_DigestUpdate(h,mc,64)!=1||EVP_DigestFinal_ex(h,d,&dn)!=1||dn!=32){if(h)EVP_MD_CTX_free(h);free(cfg.p);return-3;}EVP_MD_CTX_free(h);uint32_t start=((uint32_t)d[0]<<24|((uint32_t)d[1]<<16)|((uint32_t)d[2]<<8)|d[3])%cn;uint32_t compute=0;for(uint32_t k=0;k<cn&&(fetched<p->bytes_to_place||!compute);k++){uint32_t i=cand[(start+k)%cn];const QrxAuraModelAsset*x=&a->manifest.assets[i];if(asset_fetch_known(&c->origin,map.repo_id,map.revision,map.files[i].path,x->bytes,c->local_cache,x->content_root)){free(cfg.p);return-4;}fetched+=x->bytes;compute++;}
    uint8_t*smb=NULL;size_t smn=0;char smroot[65];if(qrx_aura_origin_source_map_encode(&map,&smb,&smn)||qrx_storage_fs_put(c->local_cache,smb,smn,smroot)){free(smb);free(cfg.p);return-5;}free(smb);QrxAuraModelBundleManifest b={0};b.version=QRX_AURA_MODEL_BUNDLE_VERSION;textcpy(b.model_id,sizeof(b.model_id),model->model_id);textcpy(b.model_version,sizeof(b.model_version),model->model_version);for(uint32_t i=0;i<map.file_count;i++)if(add_bundle(&b,bundle_kind(map.files[i].kind),map.files[i].bytes,map.files[i].content_root)){free(cfg.p);return-5;}if(add_bundle(&b,QRX_AURA_MODEL_OBJECT_SOURCE_MAP,smn,smroot)){free(cfg.p);return-5;}
    if(model->is_moe){if(!cfg.p){free(cfg.p);return-6;}const char*lk[]={"num_hidden_layers","num_layers","n_layer"};const char*ek[]={"n_routed_experts","num_local_experts","num_experts","moe_num_experts"};const char*tk[]={"num_experts_per_tok","num_experts_per_token","num_selected_experts","moe_top_k"};QrxAuraExpertManifest em={0};em.version=1;textcpy(em.model_id,sizeof(em.model_id),model->model_id);textcpy(em.model_version,sizeof(em.model_version),model->model_version);textcpy(em.architecture,sizeof(em.architecture),model->architecture);em.layer_count=first_u32((char*)cfg.p,lk,3,1);em.expert_count=first_u32((char*)cfg.p,ek,4,0);em.experts_per_token=first_u32((char*)cfg.p,tk,4,0);if(!em.expert_count||!em.experts_per_token){free(cfg.p);return-6;}uint8_t*eb=NULL;size_t en=0;char er[65];if(qrx_aura_expert_manifest_encode(&em,&eb,&en)||qrx_storage_fs_put(c->local_cache,eb,en,er)){free(eb);free(cfg.p);return-6;}free(eb);if(strcmp(er,model->expert_manifest_root)||add_bundle(&b,QRX_AURA_MODEL_OBJECT_EXPERT_MANIFEST,en,er)){free(cfg.p);return-6;}}
    free(cfg.p);uint8_t*bb=NULL;size_t bn=0;char br[65];if(qrx_aura_model_bundle_encode(&b,&bb,&bn)||qrx_storage_fs_put(c->local_cache,bb,bn,br)){free(bb);return-7;}free(bb);if(strcmp(br,model->manifest_root))return-8;if(fetched<p->bytes_to_place)return-9;textcpy(out,65,mc);return 0;}
int qrx_aura_model_fetch_drive_then_origin(void*v,const QrxAiModelRecord*m,const QrxAuraModelCachePlacement*p,char out[65]){QrxAuraOriginFallbackFetchContext*c=v;if(!c||!m||!p||!out||!c->local_cache||!c->catalog)return-1;if(c->drive){int rc=qrx_aura_drive_model_fetch(c->drive,m,p,out);if(!rc)return 0;}if(!c->allow_origin_fallback)return-2;const QrxAuraModelCatalogAnnouncement*a=qrx_aura_model_catalog_find(c->catalog,m->model_id,m->model_version);if(!a||!a->manifest.origin_uri[0])return-3;return origin_fetch_selected(c,m,p,a,out);}
